class crawl_box
{
public:
  int type;
  vector3d pos;
  convex_box box;
  bool forced;

  crawl_box(int _type, bool _forced, const vector3d& _po, const convex_box& _box)
    : type(_type), pos(_po), box(_box), forced(_forced) { }
};

template<class T> class vector
{
  T* start;
  T* finish;
  T* end_of_storage;
public:
  void _M_insert_aux(T*, const T&);
  void push_back(const T& x)
  {
    if (finish != end_of_storage)
    {
      if (finish) *finish = x;
      ++finish;
    }
    else
      _M_insert_aux(finish, x);
  }
};

class region;
class region_node
{
  void* released_link;
  region* data;
public:
  region* get_data() const { return data; }
};

class sector
{
  region_node* my_region;
public:
  region_node* get_region() const { return my_region; }
};

class terrain
{
public:
  sector* find_sector(const vector3d& pos) const;
};

class region
{
public:
  void add(crawl_box*);
};

void warning(const char*, ...);

class world_dynamics_system
{
  unsigned char released_before_crawl_boxes[124];
  vector<crawl_box*> crawl_boxes;
  unsigned char released_before_terrain[100];
  terrain* the_terrain;
public:
  void add_crawl_box(int type, bool forced, const vector3d& where, const convex_box& binfo);
};

void world_dynamics_system::add_crawl_box( int type, bool forced, const vector3d& where, const convex_box& binfo )
{
	crawl_box* crawl = NEW crawl_box( type, forced, where, binfo );

	// wds 'owns' all crawl boxes for memory tracking purposes
	crawl_boxes.push_back( crawl );

	//#pragma fixme( "crawl box has volume, so it can straddle regions. -mkv 4/6/01" )
	sector* sector = the_terrain->find_sector( where );
	region_node* rnode = sector != 0 ? sector->get_region() : 0;
	region* reg = rnode != 0 ? rnode->get_data() : 0;

	if(reg != 0)
		reg->add( crawl );
	else
		warning("Crawl box placed outside world at <%.3f, %.3f, %.3f>", where.x, where.y, where.z);
}
